local function pre9FindSub(list, name)
	if type(list) ~= "table" then
		return nil
	end
	for i = 1, #list - 1, 2 do
		if list[i] == name and type(list[i + 1]) == "table" then
			return list[i + 1]
		end
	end
	return nil
end

local frogPath = "object/tangible/terminal/terminal_character_builder.iff"
local frog = ObjectTemplates[crcString(frogPath)]
local cityDeeds = frog and pre9FindSub(pre9FindSub(pre9FindSub(frog.itemList, "Items"), "Deeds"), "City Deeds")
local added = 0

if cityDeeds ~= nil then
	for _, p in ipairs({"Corellia", "Naboo", "Tatooine"}) do
		local sub = pre9FindSub(cityDeeds, p)
		if sub ~= nil then
			sub[#sub + 1] = "Starport"
			sub[#sub + 1] = "object/tangible/deed/city_deed/starport_" .. string.lower(p) .. "_deed.iff"
			added = added + 1
		end
	end
	ObjectTemplates:addTemplate(frog, frogPath)
end

print("pre9_starports: registered 3 starport variants (deed+building+schematic), frog entries added: " .. added)
